export function sortedByWomenShare(rows: TradeSexRow[], desc = true): TradeSexRow[] {
  return [...rows].sort((a, b) =>
    desc ? b.womenSharePct - a.womenSharePct : a.womenSharePct - b.womenSharePct,
  );
}

