  construction: "Construction",
  health: "Health",
  "care-education": "Care & education",
  transport: "Transport",
  "public-safety": "Public safety",
  other: "Other",
};

const PANEL_META: Record<Panel, { title: string; subtitle: string }> = {
  "system-trend": {
