      </div>

      <div className="mb-4 flex flex-wrap gap-2">
        {(Object.keys(PANEL_META) as Panel[]).map((id) => (
          <ControlChip key={id} active={panel === id} onClick={() => setPanel(id)}>
            {id === "system-trend"
              ? "System trend"
              : id === "trade-ladder"
