export function PostVisualization({
  type,
  embedded = false,
}: {
  type: NonNullable<import("@/types/post").Post["visualization"]>;
  embedded?: boolean;
}) {
  if (type === "gdp-analysis") {
    return <GdpInteractiveDashboard />;
  }
  if (type === "subsidies-tariffs") {
    return <SubsidiesTariffsDashboard />;
