  publishedAt: '2026-08-23T20:00:00Z',
  featured: true,
  visualization: 'women-and-men-in-apprentice-trades-2026',
  layout: 'default',
  content: body,
};
function serialize(obj){
  const lines=[];
  lines.push('  {');
  for (const [k,v] of Object.entries(obj)){
    if (k==='content'){
      lines.push('    content: \`'+v.replace(/\\\\/g,'\\\\\\\\').replace(/\`/g,'\\\\\`').replace(/\$\{/g,'\\\\\${')+'\`,');
    } else if (typeof v==='string'){
      lines.push('    '+k+': '+JSON.stringify(v)+',');
    } else if (typeof v==='boolean'){
      lines.push('    '+k+': '+v+',');
    } else {
      lines.push('    '+k+': '+JSON.stringify(v)+',');
    }
  }
  lines.push('  },');
  return lines.join('\n');
}
const path='src/data/posts.ts';
let s=fs.readFileSync(path,'utf8');
const marker='export const samplePosts: Post[] = [';
const idx=s.indexOf(marker);
if(idx<0) throw new Error('marker missing');
